// Typed access layer over the key/value `Setting` store (db.setting).
//
// Plain (non-"use server") module so it can export the SETTINGS_DEFAULTS map,
// types and pure helpers alongside the async DB getters/setters. Import it from
// server components, server actions and the worker. Do NOT import from client
// components.
//
// Every admin-editable knob lives here with a default, so reads are total: a key
// that has never been written falls back to its SETTINGS_DEFAULTS value. Booleans
// are stored as the strings "true"/"false"; money is stored in cents; percents as
// plain numbers (e.g. "8.5" = 8.5%).

import { db } from "./db";

export const SETTINGS_DEFAULTS = {
  // --- General / Branding ---
  brand_name: "Nxeon",
  brand_tagline: "Premium VPS hosting, provisioned in seconds.",
  support_email: "",
  company_legal_name: "",
  company_address: "",
  social_twitter: "",
  social_github: "",
  social_discord: "",
  social_linkedin: "",
  footer_text: "",
  // Raw provider <script> body injected by components/marketing/LiveChat.tsx.
  livechat_snippet: "",
  // Business-email DNS guidance shown to customers (MX host + SPF include).
  email_mx_host: "mx.nxeon.email",
  email_spf_include: "_spf.nxeon.email",

  // --- Billing ---
  currency: "USD",
  tax_percent: "0",
  min_topup_cents: "500",
  default_term: "monthly",
  invoice_prefix: "INV-",
  dunning_grace_days: "3",
  dunning_warn_days: "7",
  dunning_terminate_days: "14",
  auto_suspend_enabled: "true",
  // Block storage: price per GB per month (lib/actions-volumes.ts volumePriceCents).
  volume_price_cents_per_gb: "10",
  // Per-server EXTRA ROOT DISK: price per GB per month, priced to match block
  // storage (10 = $0.10/GB/mo). Read via extraDiskPerGbCents()/extraDiskMonthlyCents()
  // in lib/disk-expand.ts — the single source of truth for the deploy-time upsell,
  // the post-deploy "Add storage" action and every renewal.
  extra_disk_gb_price_cents: "10",

  // --- Domains ---
  domain_markup_percent: "0",
  whois_privacy_default: "true",

  // --- Dedicated IP ---
  // 0 = included: every server gets a dedicated IPv4 and its cost is folded into
  // the plan price (see prisma/seed.ts), so no separate surcharge is billed.
  dedicated_ip_price_cents: "0",
  dedicated_ip_replenish_threshold: "3",
  dedicated_ip_autoreplenish: "false",

  // --- Provisioning & limits ---
  default_plan_slug: "",
  max_servers_per_user: "10",
  signup_free_credit_cents: "0",
  maintenance_mode: "false",
  maintenance_message: "We're performing scheduled maintenance and will be back shortly.",

  // --- Growth ---
  referral_reward_cents: "500",
  coupons_enabled: "true",

  // --- Email / SMTP --- (keys mirror lib/mailer.ts)
  smtp_host: "",
  smtp_port: "587",
  smtp_user: "",
  smtp_pass: "",
  smtp_from: "",
  smtp_secure: "false",

  // --- Security ---
  enforce_staff_2fa: "false",
  session_length_days: "30",
  login_ratelimit_max: "10",
  // Outbound-abuse detection (worker/abuse.ts): sustained outbound Mbps that
  // raises an alert, and whether to auto-suspend the worst (3×) offenders.
  abuse_outbound_mbps: "200",
  abuse_autosuspend: "false",
  allowed_admin_ips: "",

  // --- Feature flags ---
  feature_game_servers: "true",
  feature_claude_builder: "true",
  feature_domains: "true",
  feature_newsletter: "true",
  feature_referrals: "true",
} as const;

export type SettingKey = keyof typeof SETTINGS_DEFAULTS;

/** Keys whose stored value is a secret — never rendered back to the browser. */
export const SECRET_KEYS: readonly string[] = ["smtp_pass"] as const;

/** True-ish coercion for values stored as "true"/"false"/"on"/"1". */
export function isTrue(v: string | undefined | null): boolean {
  return v === "true" || v === "on" || v === "1";
}

/** Read one setting, falling back to an explicit default then SETTINGS_DEFAULTS. */
export async function getSetting(key: SettingKey | string, fallback?: string): Promise<string> {
  const row = await db.setting.findUnique({ where: { key } });
  if (row) return row.value;
  return fallback ?? SETTINGS_DEFAULTS[key as SettingKey] ?? "";
}

/** Read one setting as a boolean. */
export async function getSettingBool(key: SettingKey | string, fallback = false): Promise<boolean> {
  const row = await db.setting.findUnique({ where: { key } });
  if (row) return isTrue(row.value);
  const def = SETTINGS_DEFAULTS[key as SettingKey];
  return def !== undefined ? isTrue(def) : fallback;
}

/** Read one setting as an integer (cents, days, counts…). */
export async function getSettingInt(key: SettingKey | string, fallback = 0): Promise<number> {
  const raw = await getSetting(key, String(fallback));
  const n = Number(raw);
  return Number.isFinite(n) ? n : fallback;
}

/** Upsert one setting. */
export async function setSetting(key: SettingKey | string, value: string): Promise<void> {
  await db.setting.upsert({
    where: { key },
    update: { value },
    create: { key, value },
  });
}

/**
 * Every setting, with defaults merged under any stored overrides. Secret values
 * ARE included — callers that hand this to the client (the settings page) must
 * strip SECRET_KEYS themselves.
 */
export async function getAllSettings(): Promise<Record<string, string>> {
  const rows = await db.setting.findMany();
  const merged: Record<string, string> = { ...SETTINGS_DEFAULTS };
  for (const r of rows) merged[r.key] = r.value;
  return merged;
}
